macro.xml_pipeline.wide_array_expr.macro_sql:
{% macro wide_array_expr(tag, m) -%}
{%- set key = tag ~ '_' ~ m -%}
{%- set g = "element_at(g, '" ~ key ~ "')" -%}
CASE WHEN {{ g }} IS NULL THEN NULL ELSE transform(sequence(1, array_max(transform({{ g }}, x -> x.s))), i -> element_at(transform(filter({{ g }}, x -> x.s = i), x -> x.val), 1)) END
{%- endmacro %}

macro.xml_pipeline.get_wide_select.macro_sql:
{% macro get_wide_select(rows, array_cols, watermark_field) %}
  {%- set columns = ['  recid'] -%}
  {%- set names = ['recid'] -%}
  {%- for r in rows -%}
    {%- set col = '"' ~ r.name.replace('"', '""') ~ '"' -%}
    {%- do names.append(r.name) -%}
    {%- if r.tag == 'c0' -%}
      {%- do columns.append('  recid AS ' ~ col) -%}
    {%- elif (r.tag, r.m) in array_cols -%}
      {%- do columns.append('  ' ~ wide_array_expr(r.tag, r.m) ~ ' AS ' ~ col) -%}
    {%- else -%}
      {%- do columns.append('  ' ~ wide_scalar_expr(r.tag, r.m) ~ ' AS ' ~ col) -%}
    {%- endif -%}
  {%- endfor -%}
  {%- do columns.append("  TRY(CAST(date_parse(element_at(f, '" ~ watermark_field ~ "_1'), '%Y%m%d') AS DATE)) AS source_updated_date") -%}
  {%- do names.append('source_updated_date') -%}
  {{ return((columns | join(',\n'), names)) }}
{% endmacro %}

macro.xml_pipeline.wide_pivot_cte.macro_sql:
{% macro wide_pivot_cte(source) %}
WITH grouped AS (
  SELECT
    recid,
    map_agg(field_index || '_' || CAST(m_index AS VARCHAR), field_value) AS f,
    multimap_agg(
      field_index || '_' || CAST(m_index AS VARCHAR),
      CAST(ROW(s_index, field_value) AS ROW(s INTEGER, val VARCHAR))
    ) AS g,
    max(xml_hash) AS xml_hash
  FROM {{ source }}
  GROUP BY recid
)
{%- endmacro %}

macro.xml_pipeline.reconcile_wide_schema.macro_sql:
{% macro reconcile_wide_schema(table_name) %}
  {% if not execute %}
    {{ return(none) }}
  {% endif %}

  {% set wide_relation = ref(table_name ~ '_wide') %}
  {% set attrs_relation = ref(table_name ~ '_attributes') %}
  {% set existing = adapter.get_relation(wide_relation.database, wide_relation.schema, wide_relation.identifier) %}

  {% if existing is none %}
    {{ log('reconcile_wide_schema: ' ~ wide_relation ~ ' does not exist yet -- nothing to migrate', info=True) }}
    {{ return(none) }}
  {% endif %}

  {% set rows = get_lookup_rows(table_name) %}
  {% set pairs = [] %}
  {% for r in rows if r.tag != 'c0' %}
    {% if (r.tag, r.m) not in pairs %}
      {% do pairs.append((r.tag, r.m)) %}
    {% endif %}
  {% endfor %}
  {% if pairs | length == 0 %}
    {{ return(none) }}
  {% endif %}

  {#-- detect_batch_shapes(): does account_attributes currently have s_index > 1
       for a given lookup row's (field_index, m_index)? #}
  {% set conditions = [] %}
  {% for t, m in pairs %}
    {% do conditions.append("(field_index = '" ~ t ~ "' AND m_index = " ~ m ~ ")") %}
  {% endfor %}
  {% set shape_query %}
    SELECT field_index, m_index, max(s_index) AS max_s
    FROM {{ attrs_relation }}
    WHERE {{ conditions | join(' OR ') }}
    GROUP BY field_index, m_index
  {% endset %}
  {% set batch_shapes = {} %}
  {% for t, m, s in run_query(shape_query).rows %}
    {% do batch_shapes.update({(t, m): s}) %}
  {% endfor %}

  {#-- read_table_types(): account_wide's current column types #}
  {% set type_query %}
    SELECT column_name, data_type
    FROM {{ wide_relation.database }}.information_schema.columns
    WHERE table_schema = '{{ wide_relation.schema }}' AND table_name = '{{ wide_relation.identifier }}'
  {% endset %}
  {% set table_types = {} %}
  {% for name, dtype in run_query(type_query).rows %}
    {% do table_types.update({name: dtype}) %}
  {% endfor %}

  {% set name_by_tag_m = {} %}
  {% for r in rows %}
    {% do name_by_tag_m.update({(r.tag, r.m): r.name}) %}
  {% endfor %}

  {#-- reconcile(): for any lookup row whose batch shape is wider than the
       table's current column, migrate -- mirrors _migrate_table_column() #}
  {% set migrated = [] %}
  {% for key, max_s in batch_shapes.items() %}
    {% set name = name_by_tag_m.get(key) %}
    {% if name is not none %}
      {% set current_type = table_types.get(name) %}
      {% set is_array_now = current_type is not none and current_type.upper().startswith('ARRAY') %}
      {% set needs_array = max_s is not none and max_s > 1 %}
      {% if needs_array and current_type is not none and not is_array_now %}
        {% do migrate_wide_column_to_array(wide_relation, name) %}
        {% do migrated.append(name) %}
      {% endif %}
    {% endif %}
  {% endfor %}

  {% if migrated | length > 0 %}
    {{ log('reconcile_wide_schema: migrated to ARRAY(VARCHAR): ' ~ migrated, info=True) }}
  {% else %}
    {{ log('reconcile_wide_schema: no columns needed widening', info=True) }}
  {% endif %}
{% endmacro %}

macro.xml_pipeline.migrate_wide_column_t.macro_sql:
{% macro migrate_wide_column_to_array(wide_relation, col_name) %}
  {% set tmp = col_name ~ '_v2' %}
  {{ log('  migrating "' ~ col_name ~ '": VARCHAR -> ARRAY(VARCHAR)', info=True) }}
  {% do run_query('ALTER TABLE ' ~ wide_relation ~ ' ADD COLUMN "' ~ tmp ~ '" ARRAY(VARCHAR)') %}
  {% do run_query('UPDATE ' ~ wide_relation ~ ' SET "' ~ tmp ~ '" = CASE WHEN "' ~ col_name ~ '" IS NULL THEN NULL ELSE ARRAY["' ~ col_name ~ '"] END') %}
  {% do run_query('ALTER TABLE ' ~ wide_relation ~ ' DROP COLUMN "' ~ col_name ~ '"') %}
  {% do run_query('ALTER TABLE ' ~ wide_relation ~ ' RENAME COLUMN "' ~ tmp ~ '" TO "' ~ col_name ~ '"') %}
{% endmacro %}

macro.xml_pipeline.raw_ingest_model.macro_sql:
{% macro raw_ingest_model() %}

{%- set suffix = '_raw' -%}
{%- set table_name = model.name[:-(suffix | length)] -%}
{%- set watermark_field = var('watermark_field', 'c167') -%}
{%- set start_date = var('start_date', none) -%}
{%- set end_date = var('end_date', none) -%}
{%- if (start_date is not none) != (end_date is not none) -%}
  {{ exceptions.raise_compiler_error("start_date and end_date vars must be given together") }}
{%- endif -%}

{%- set where_clause -%}
{%- if start_date -%}
    WHERE XMLCAST(
      XMLQUERY(''/row/{{ watermark_field }}/text()'' PASSING a.xmlrecord RETURNING CONTENT)
      AS VARCHAR2(8)
    ) BETWEEN ''{{ start_date }}'' AND ''{{ end_date }}''
{%- endif -%}
{%- endset -%}

SELECT
  recid,
  xmlrecord,
  current_timestamp AS ingested_at
FROM TABLE(
  oracle.system.query(
    query => 'SELECT
      a.recid,
      a.xmlrecord.getClobVal() AS xmlrecord
    FROM {{ var("oracle_schema") }}.{{ table_name }} a{{ where_clause }}'
  )
)
{%- endmacro %}

